type MigrationPool = { connect(): Promise<{ query(sql: string): Promise<unknown>; release(): void }> };
export const FEEDBACK_SCHEMA_ADVISORY_LOCK = 1603508;

export async function ensureFeedbackSchema(pool: MigrationPool) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(`SELECT pg_advisory_xact_lock(${FEEDBACK_SCHEMA_ADVISORY_LOCK})`);
    const statements = [
      `CREATE TABLE IF NOT EXISTS feedback_items (id serial PRIMARY KEY,user_id integer NOT NULL REFERENCES users(id),project_id integer REFERENCES projects(id),feedback_type text NOT NULL,priority text NOT NULL DEFAULT 'normal',module text,page_url text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'new',stable_id text,company_id integer,owner_user_id integer REFERENCES users(id),target_release text,disposition_reason text,customer_visible boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,idempotency_key text,request_hash text,transcript text,transcript_provenance text,metadata jsonb,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),resolved_at timestamp)`,
      `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS stable_id text`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS company_id integer`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS owner_user_id integer REFERENCES users(id)`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS target_release text`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS disposition_reason text`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS customer_visible boolean NOT NULL DEFAULT true`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS idempotency_key text`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS request_hash text`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS transcript text`, `ALTER TABLE feedback_items ADD COLUMN IF NOT EXISTS transcript_provenance text`,
      `UPDATE feedback_items SET status=CASE status WHEN 'open' THEN 'new' WHEN 'in_review' THEN 'triaged' WHEN 'planned' THEN 'accepted' WHEN 'done' THEN 'verified' ELSE status END WHERE status IN ('open','in_review','planned','done')`,
      `UPDATE feedback_items SET stable_id='FB-'||lpad(id::text,8,'0') WHERE stable_id IS NULL`, `UPDATE feedback_items f SET company_id=u.company_id FROM users u WHERE f.user_id=u.id AND f.company_id IS NULL`,
      `ALTER TABLE feedback_items ALTER COLUMN stable_id SET NOT NULL`, `ALTER TABLE feedback_items ALTER COLUMN company_id SET NOT NULL`,
      `DO $$ BEGIN ALTER TABLE feedback_items ADD CONSTRAINT feedback_items_company_id_fkey FOREIGN KEY(company_id) REFERENCES companies(id); EXCEPTION WHEN duplicate_object THEN NULL; END $$`, `DO $$ BEGIN ALTER TABLE feedback_items ADD CONSTRAINT feedback_items_status_chk CHECK(status IN ('new','triaged','accepted','in_progress','blocked','fixed','verified','rejected','deferred')); EXCEPTION WHEN duplicate_object THEN NULL; END $$`, `DO $$ BEGIN ALTER TABLE feedback_items ADD CONSTRAINT feedback_items_version_chk CHECK(version>0); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
      `CREATE UNIQUE INDEX IF NOT EXISTS feedback_items_stable_id_idx ON feedback_items(stable_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_items_user_idempotency_idx ON feedback_items(user_id,idempotency_key) WHERE idempotency_key IS NOT NULL`, `CREATE INDEX IF NOT EXISTS feedback_items_status_created_idx ON feedback_items(status,created_at DESC)`, `CREATE INDEX IF NOT EXISTS feedback_items_user_created_idx ON feedback_items(user_id,created_at DESC)`, `CREATE INDEX IF NOT EXISTS feedback_items_project_created_idx ON feedback_items(project_id,created_at DESC)`,
      `CREATE TABLE IF NOT EXISTS feedback_assets (id serial PRIMARY KEY,feedback_id integer NOT NULL REFERENCES feedback_items(id),project_id integer REFERENCES projects(id),uploaded_by_id integer NOT NULL REFERENCES users(id),kind text NOT NULL,original_name text NOT NULL,safe_name text NOT NULL,media_type text NOT NULL,byte_size bigint NOT NULL,sha256 text NOT NULL,storage_path text NOT NULL,scan_state text NOT NULL DEFAULT 'quarantined',scanner_adapter text NOT NULL DEFAULT 'default-deny',scanned_at timestamp,retention_hold boolean NOT NULL DEFAULT true,expires_at timestamp,provenance jsonb NOT NULL DEFAULT '{}',created_at timestamp NOT NULL DEFAULT now())`,
      `ALTER TABLE feedback_assets ADD COLUMN IF NOT EXISTS scanner_adapter text NOT NULL DEFAULT 'default-deny'`, `ALTER TABLE feedback_assets ADD COLUMN IF NOT EXISTS scanned_at timestamp`, `ALTER TABLE feedback_assets ADD COLUMN IF NOT EXISTS retention_hold boolean NOT NULL DEFAULT true`, `ALTER TABLE feedback_assets ADD COLUMN IF NOT EXISTS expires_at timestamp`, `ALTER TABLE feedback_assets ADD COLUMN IF NOT EXISTS provenance jsonb NOT NULL DEFAULT '{}'`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_assets_feedback_hash_idx ON feedback_assets(feedback_id,sha256)`,
      `CREATE TABLE IF NOT EXISTS feedback_audit_events (id serial PRIMARY KEY,feedback_id integer NOT NULL REFERENCES feedback_items(id),actor_user_id integer NOT NULL REFERENCES users(id),event_type text NOT NULL,before_state jsonb,after_state jsonb,reason text,created_at timestamp NOT NULL DEFAULT now())`, `CREATE INDEX IF NOT EXISTS feedback_audit_feedback_idx ON feedback_audit_events(feedback_id,created_at)`,
      `CREATE TABLE IF NOT EXISTS feedback_capture_consents (id text PRIMARY KEY,actor_user_id integer NOT NULL REFERENCES users(id),feedback_id integer REFERENCES feedback_items(id),capture_kind text NOT NULL,purpose text NOT NULL,notice_version text NOT NULL,granted_at timestamp NOT NULL DEFAULT now(),revoked_at timestamp)`, `CREATE INDEX IF NOT EXISTS feedback_capture_consents_actor_idx ON feedback_capture_consents(actor_user_id,granted_at)`,
      `CREATE TABLE IF NOT EXISTS feedback_transcription_jobs (id serial PRIMARY KEY,feedback_id integer NOT NULL REFERENCES feedback_items(id),asset_id integer NOT NULL REFERENCES feedback_assets(id),requested_by_id integer NOT NULL REFERENCES users(id),state text NOT NULL DEFAULT 'queued',adapter text NOT NULL,result text,error_code text,attempts integer NOT NULL DEFAULT 0,request_key text NOT NULL,request_hash text NOT NULL,consent_id text NOT NULL REFERENCES feedback_capture_consents(id),provider text NOT NULL,model text NOT NULL,adapter_version text NOT NULL,source_sha256 text NOT NULL,output_sha256 text,completed_at timestamp,review_state text NOT NULL DEFAULT 'pending',reviewed_by_id integer REFERENCES users(id),reviewed_at timestamp,review_reason text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now())`,
      `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS request_key text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS request_hash text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS consent_id text REFERENCES feedback_capture_consents(id)`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS provider text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS model text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS adapter_version text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS source_sha256 text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS output_sha256 text`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS completed_at timestamp`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS review_state text NOT NULL DEFAULT 'pending'`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS reviewed_by_id integer REFERENCES users(id)`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS reviewed_at timestamp`, `ALTER TABLE feedback_transcription_jobs ADD COLUMN IF NOT EXISTS review_reason text`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_transcription_request_idx ON feedback_transcription_jobs(requested_by_id,request_key)`,
      ...feedbackRelayStatements,
    ];
    for (const statement of statements) await client.query(statement);
    await client.query("COMMIT");
  } catch (error) { await client.query("ROLLBACK"); throw error; } finally { client.release(); }
}

const feedbackRelayStatements = [
  `CREATE TABLE IF NOT EXISTS feedback_relay_jobs (id bigserial PRIMARY KEY,feedback_id integer NOT NULL REFERENCES feedback_items(id),asset_id integer NOT NULL REFERENCES feedback_assets(id),company_id integer NOT NULL REFERENCES companies(id),project_id integer REFERENCES projects(id),state text NOT NULL DEFAULT 'queued',version integer NOT NULL DEFAULT 1,relay_mode text NOT NULL,direction text NOT NULL DEFAULT 'outbound',destination_id text NOT NULL,object_id text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,source_byte_count bigint NOT NULL,source_sha256 text NOT NULL,policy_id text NOT NULL,policy_version text NOT NULL,policy_sha256 text NOT NULL,lineage_id text NOT NULL,parent_job_id bigint REFERENCES feedback_relay_jobs(id),receipt_id bigint,deletion_proof_id bigint,expires_at timestamp,expiry_outcome text,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamp,lease_owner text,lease_token text,lease_expires_at timestamp,fencing_token bigint NOT NULL DEFAULT 0,last_error_code text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),CONSTRAINT feedback_relay_jobs_state_chk CHECK(state IN ('queued','transferring','delivered','receipt-verified','cleanup-pending','manual-review','held','expired')),CONSTRAINT feedback_relay_jobs_mode_chk CHECK(relay_mode IN ('direct','queue')),CONSTRAINT feedback_relay_jobs_direction_chk CHECK(direction='outbound'),CONSTRAINT feedback_relay_jobs_version_chk CHECK(version>0),CONSTRAINT feedback_relay_jobs_attempts_chk CHECK(attempts>=0),CONSTRAINT feedback_relay_jobs_fencing_chk CHECK(fencing_token>=0),CONSTRAINT feedback_relay_jobs_source_chk CHECK(source_byte_count>=0 AND source_sha256 ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_jobs_request_hash_chk CHECK(request_hash ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_jobs_policy_hash_chk CHECK(policy_sha256 ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_jobs_expiry_chk CHECK((state='expired' AND expires_at IS NOT NULL AND expiry_outcome IS NOT NULL) OR (state<>'expired' AND expiry_outcome IS NULL)),CONSTRAINT feedback_relay_jobs_lease_chk CHECK((lease_owner IS NULL AND lease_token IS NULL AND lease_expires_at IS NULL) OR (lease_owner IS NOT NULL AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL)))`,
  `DROP TRIGGER IF EXISTS feedback_relay_jobs_guard_fence ON feedback_relay_jobs`,
  ...["relay_mode text","direction text","idempotency_key text","request_hash text","source_byte_count bigint","source_sha256 text","lineage_id text","parent_job_id bigint","receipt_id bigint","deletion_proof_id bigint","expires_at timestamp","expiry_outcome text"].map(definition => `ALTER TABLE feedback_relay_jobs ADD COLUMN IF NOT EXISTS ${definition}`),
  `UPDATE feedback_relay_jobs j SET relay_mode=COALESCE(j.relay_mode,'queue'),direction=COALESCE(j.direction,'outbound'),idempotency_key=COALESCE(j.idempotency_key,'legacy:'||j.id::text),request_hash=COALESCE(j.request_hash,encode(sha256(convert_to(j.destination_id||E'\n'||j.object_id||E'\n'||j.id::text,'UTF8')),'hex')),source_byte_count=COALESCE(j.source_byte_count,a.byte_size),source_sha256=COALESCE(j.source_sha256,a.sha256),lineage_id=COALESCE(j.lineage_id,'legacy:'||j.id::text),state=CASE WHEN j.state IN ('delivered','cleanup-pending','expired') AND j.receipt_id IS NULL THEN 'manual-review' ELSE j.state END FROM feedback_assets a WHERE a.id=j.asset_id`,
  `ALTER TABLE feedback_relay_jobs ALTER COLUMN relay_mode SET NOT NULL`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN direction SET NOT NULL`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN direction SET DEFAULT 'outbound'`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN idempotency_key SET NOT NULL`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN request_hash SET NOT NULL`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN source_byte_count SET NOT NULL`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN source_sha256 SET NOT NULL`, `ALTER TABLE feedback_relay_jobs ALTER COLUMN lineage_id SET NOT NULL`,
  `ALTER TABLE feedback_relay_jobs DROP CONSTRAINT IF EXISTS feedback_relay_jobs_state_chk`, `DO $$ BEGIN ALTER TABLE feedback_relay_jobs ADD CONSTRAINT feedback_relay_jobs_state_chk CHECK(state IN ('queued','transferring','delivered','receipt-verified','cleanup-pending','manual-review','held','expired')); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  ...[["feedback_relay_jobs_mode_chk","relay_mode IN ('direct','queue')"],["feedback_relay_jobs_direction_chk","direction='outbound'"],["feedback_relay_jobs_source_chk","source_byte_count>=0 AND source_sha256 ~ '^[a-f0-9]{64}$'"],["feedback_relay_jobs_request_hash_chk","request_hash ~ '^[a-f0-9]{64}$'"],["feedback_relay_jobs_expiry_chk","(state='expired' AND expires_at IS NOT NULL AND expiry_outcome IS NOT NULL) OR (state<>'expired' AND expiry_outcome IS NULL)"]].map(([name,predicate]) => `DO $$ BEGIN ALTER TABLE feedback_relay_jobs ADD CONSTRAINT ${name} CHECK(${predicate}); EXCEPTION WHEN duplicate_object THEN NULL; END $$`),
  `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_jobs_asset_destination_idx ON feedback_relay_jobs(asset_id,destination_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_jobs_object_destination_idx ON feedback_relay_jobs(destination_id,object_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_jobs_idempotency_idx ON feedback_relay_jobs(company_id,destination_id,idempotency_key)`, `CREATE INDEX IF NOT EXISTS feedback_relay_jobs_claim_idx ON feedback_relay_jobs(state,next_attempt_at,lease_expires_at,id)`, `CREATE INDEX IF NOT EXISTS feedback_relay_jobs_scope_idx ON feedback_relay_jobs(company_id,project_id,created_at DESC)`,
  `CREATE OR REPLACE FUNCTION feedback_relay_derive_job_scope() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a feedback_assets%ROWTYPE; f feedback_items%ROWTYPE; parent feedback_relay_jobs%ROWTYPE; canonical_project integer; reporter_company integer; uploader_company integer; project_company integer; BEGIN SELECT * INTO a FROM feedback_assets WHERE id=NEW.asset_id FOR SHARE; IF NOT FOUND OR a.scan_state<>'clean' OR a.scanned_at IS NULL THEN RAISE EXCEPTION 'feedback relay clean scanned asset required'; END IF; SELECT * INTO f FROM feedback_items WHERE id=a.feedback_id FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'feedback relay feedback does not exist'; END IF; canonical_project:=COALESCE(a.project_id,f.project_id); SELECT company_id INTO reporter_company FROM users WHERE id=f.user_id FOR SHARE; SELECT company_id INTO uploader_company FROM users WHERE id=a.uploaded_by_id FOR SHARE; IF canonical_project IS NOT NULL THEN SELECT u.company_id INTO project_company FROM projects p JOIN users u ON u.id=p.created_by_id WHERE p.id=canonical_project FOR SHARE OF p,u; END IF; IF reporter_company IS DISTINCT FROM f.company_id OR uploader_company IS DISTINCT FROM f.company_id OR (canonical_project IS NOT NULL AND project_company IS DISTINCT FROM f.company_id) THEN RAISE EXCEPTION 'feedback relay canonical tenant authority mismatch'; END IF; IF NEW.feedback_id IS NOT NULL AND NEW.feedback_id<>f.id THEN RAISE EXCEPTION 'feedback relay feedback mismatch'; END IF; IF NEW.company_id IS NOT NULL AND NEW.company_id<>f.company_id THEN RAISE EXCEPTION 'feedback relay company mismatch'; END IF; IF NEW.project_id IS NOT NULL AND NEW.project_id IS DISTINCT FROM canonical_project THEN RAISE EXCEPTION 'feedback relay project mismatch'; END IF; IF a.project_id IS NOT NULL AND f.project_id IS DISTINCT FROM a.project_id THEN RAISE EXCEPTION 'feedback relay asset project mismatch'; END IF; IF NEW.source_byte_count<>a.byte_size OR NEW.source_sha256<>a.sha256 THEN RAISE EXCEPTION 'feedback relay source snapshot mismatch'; END IF; IF NEW.parent_job_id IS NOT NULL THEN SELECT * INTO parent FROM feedback_relay_jobs WHERE id=NEW.parent_job_id FOR SHARE; IF NOT FOUND OR parent.id=NEW.id OR ROW(parent.feedback_id,parent.company_id,parent.project_id,parent.lineage_id) IS DISTINCT FROM ROW(f.id,f.company_id,canonical_project,NEW.lineage_id) THEN RAISE EXCEPTION 'feedback relay lineage mismatch'; END IF; END IF; NEW.feedback_id:=f.id; NEW.company_id:=f.company_id; NEW.project_id:=canonical_project; RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_jobs_derive_scope BEFORE INSERT OR UPDATE OF feedback_id,asset_id,company_id,project_id ON feedback_relay_jobs FOR EACH ROW EXECUTE FUNCTION feedback_relay_derive_job_scope(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_guard_job_fence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.feedback_id,NEW.asset_id,NEW.company_id,NEW.project_id,NEW.relay_mode,NEW.direction,NEW.destination_id,NEW.object_id,NEW.idempotency_key,NEW.request_hash,NEW.source_byte_count,NEW.source_sha256,NEW.policy_id,NEW.policy_version,NEW.policy_sha256,NEW.lineage_id,NEW.parent_job_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.feedback_id,OLD.asset_id,OLD.company_id,OLD.project_id,OLD.relay_mode,OLD.direction,OLD.destination_id,OLD.object_id,OLD.idempotency_key,OLD.request_hash,OLD.source_byte_count,OLD.source_sha256,OLD.policy_id,OLD.policy_version,OLD.policy_sha256,OLD.lineage_id,OLD.parent_job_id,OLD.created_at) OR (OLD.receipt_id IS NOT NULL AND NEW.receipt_id IS DISTINCT FROM OLD.receipt_id) OR (OLD.deletion_proof_id IS NOT NULL AND NEW.deletion_proof_id IS DISTINCT FROM OLD.deletion_proof_id) OR (OLD.expiry_outcome IS NOT NULL AND NEW.expiry_outcome IS DISTINCT FROM OLD.expiry_outcome) THEN RAISE EXCEPTION 'feedback relay job identity is immutable'; END IF; IF NEW.fencing_token<OLD.fencing_token THEN RAISE EXCEPTION 'feedback relay stale fencing token'; END IF; IF NEW.lease_token IS DISTINCT FROM OLD.lease_token AND NEW.lease_token IS NOT NULL AND NEW.fencing_token<=OLD.fencing_token THEN RAISE EXCEPTION 'feedback relay lease requires a new fencing token'; END IF; IF NEW.state IS DISTINCT FROM OLD.state OR NEW.version IS DISTINCT FROM OLD.version OR NEW.receipt_id IS DISTINCT FROM OLD.receipt_id OR NEW.deletion_proof_id IS DISTINCT FROM OLD.deletion_proof_id OR NEW.expiry_outcome IS DISTINCT FROM OLD.expiry_outcome THEN IF current_setting('bimlog.feedback_relay_transition_job_id',true) IS DISTINCT FROM OLD.id::text THEN RAISE EXCEPTION 'feedback relay direct lifecycle mutation denied'; END IF; END IF; RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_jobs_guard_fence BEFORE UPDATE ON feedback_relay_jobs FOR EACH ROW EXECUTE FUNCTION feedback_relay_guard_job_fence(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE TABLE IF NOT EXISTS feedback_relay_custody_events (id bigserial PRIMARY KEY,job_id bigint NOT NULL REFERENCES feedback_relay_jobs(id),sequence integer NOT NULL,event_id text NOT NULL,event_type text NOT NULL,from_state text,to_state text NOT NULL,job_version integer NOT NULL,fencing_token bigint NOT NULL,actor_type text NOT NULL,actor_id text,reason_code text,metadata jsonb NOT NULL DEFAULT '{}',occurred_at timestamp NOT NULL DEFAULT now(),CONSTRAINT feedback_relay_custody_sequence_chk CHECK(sequence>0),CONSTRAINT feedback_relay_custody_version_chk CHECK(job_version>0),CONSTRAINT feedback_relay_custody_fencing_chk CHECK(fencing_token>=0),CONSTRAINT feedback_relay_custody_to_state_chk CHECK(to_state IN ('queued','transferring','delivered','receipt-verified','cleanup-pending','manual-review','held','expired')),CONSTRAINT feedback_relay_custody_from_state_chk CHECK(from_state IS NULL OR from_state IN ('queued','transferring','delivered','receipt-verified','cleanup-pending','manual-review','held','expired')))`,
  `ALTER TABLE feedback_relay_custody_events DROP CONSTRAINT IF EXISTS feedback_relay_custody_to_state_chk`, `ALTER TABLE feedback_relay_custody_events DROP CONSTRAINT IF EXISTS feedback_relay_custody_from_state_chk`,
  `DO $$ BEGIN ALTER TABLE feedback_relay_custody_events ADD CONSTRAINT feedback_relay_custody_to_state_chk CHECK(to_state IN ('queued','transferring','delivered','receipt-verified','cleanup-pending','manual-review','held','expired')); EXCEPTION WHEN duplicate_object THEN NULL; END $$`, `DO $$ BEGIN ALTER TABLE feedback_relay_custody_events ADD CONSTRAINT feedback_relay_custody_from_state_chk CHECK(from_state IS NULL OR from_state IN ('queued','transferring','delivered','receipt-verified','cleanup-pending','manual-review','held','expired')); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_custody_job_sequence_idx ON feedback_relay_custody_events(job_id,sequence)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_custody_event_id_idx ON feedback_relay_custody_events(event_id)`, `CREATE INDEX IF NOT EXISTS feedback_relay_custody_job_time_idx ON feedback_relay_custody_events(job_id,occurred_at,id)`,
  `CREATE OR REPLACE FUNCTION feedback_relay_validate_custody_event() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; prior feedback_relay_custody_events%ROWTYPE; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=NEW.job_id FOR UPDATE; IF NOT FOUND OR NEW.job_version<>j.version OR NEW.fencing_token<>j.fencing_token OR NEW.to_state<>j.state THEN RAISE EXCEPTION 'feedback relay custody event is stale'; END IF; SELECT * INTO prior FROM feedback_relay_custody_events WHERE job_id=NEW.job_id ORDER BY sequence DESC LIMIT 1; IF (NOT FOUND AND (NEW.sequence<>1 OR NEW.from_state IS NOT NULL)) OR (FOUND AND (NEW.sequence<>prior.sequence+1 OR NEW.from_state IS DISTINCT FROM prior.to_state)) THEN RAISE EXCEPTION 'feedback relay custody sequence mismatch'; END IF; RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_custody_events_validate BEFORE INSERT ON feedback_relay_custody_events FOR EACH ROW EXECUTE FUNCTION feedback_relay_validate_custody_event(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_initial_custody_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO feedback_relay_custody_events(job_id,sequence,event_id,event_type,from_state,to_state,job_version,fencing_token,actor_type,reason_code) VALUES(NEW.id,1,'relay-job:'||NEW.id||':v1','created',NULL,'queued',1,NEW.fencing_token,'system','relay-created'); RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_jobs_initial_custody AFTER INSERT ON feedback_relay_jobs FOR EACH ROW EXECUTE FUNCTION feedback_relay_initial_custody_event(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `INSERT INTO feedback_relay_custody_events(job_id,sequence,event_id,event_type,from_state,to_state,job_version,fencing_token,actor_type,reason_code) SELECT j.id,1,'relay-upgrade:'||j.id||':v'||j.version,'catalog-upgraded',NULL,j.state,j.version,j.fencing_token,'migration','606-catalog-preserved' FROM feedback_relay_jobs j WHERE NOT EXISTS(SELECT 1 FROM feedback_relay_custody_events e WHERE e.job_id=j.id)`,
  `CREATE TABLE IF NOT EXISTS feedback_relay_nonces (id bigserial PRIMARY KEY,authority_version text NOT NULL DEFAULT 'current',job_id bigint REFERENCES feedback_relay_jobs(id),receiver_id text,direction text,scope_id text,company_id integer REFERENCES companies(id),project_id integer REFERENCES projects(id),feedback_id integer REFERENCES feedback_items(id),asset_id integer REFERENCES feedback_assets(id),object_id text,request_hash text,audience text NOT NULL,key_id text NOT NULL,nonce text NOT NULL,request_id text NOT NULL,request_timestamp timestamp NOT NULL,consumed_at timestamp NOT NULL DEFAULT now(),expires_at timestamp NOT NULL,CONSTRAINT feedback_relay_nonces_authority_version_chk CHECK(authority_version IN ('legacy','current')),CONSTRAINT feedback_relay_nonces_current_scope_chk CHECK(authority_version='legacy' OR (job_id IS NOT NULL AND receiver_id IS NOT NULL AND direction IS NOT NULL AND scope_id IS NOT NULL AND company_id IS NOT NULL AND feedback_id IS NOT NULL AND asset_id IS NOT NULL AND object_id IS NOT NULL AND request_hash IS NOT NULL)),CONSTRAINT feedback_relay_nonces_direction_chk CHECK(direction IS NULL OR direction IN ('inbound','outbound')),CONSTRAINT feedback_relay_nonces_hash_chk CHECK(request_hash IS NULL OR request_hash ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_nonces_expiry_chk CHECK(expires_at>request_timestamp))`,
  `DROP TRIGGER IF EXISTS feedback_relay_nonces_immutable ON feedback_relay_nonces`,
  ...["authority_version text NOT NULL DEFAULT 'legacy'","job_id bigint","receiver_id text","direction text","scope_id text","company_id integer","project_id integer","feedback_id integer","asset_id integer","object_id text","request_hash text"].map(definition => `ALTER TABLE feedback_relay_nonces ADD COLUMN IF NOT EXISTS ${definition}`),
  `ALTER TABLE feedback_relay_nonces ALTER COLUMN authority_version SET DEFAULT 'current'`,
  ...[["feedback_relay_nonces_job_id_fkey","job_id","feedback_relay_jobs(id)"],["feedback_relay_nonces_company_id_fkey","company_id","companies(id)"],["feedback_relay_nonces_project_id_fkey","project_id","projects(id)"],["feedback_relay_nonces_feedback_id_fkey","feedback_id","feedback_items(id)"],["feedback_relay_nonces_asset_id_fkey","asset_id","feedback_assets(id)"]].map(([name,column,target]) => `DO $$ BEGIN ALTER TABLE feedback_relay_nonces ADD CONSTRAINT ${name} FOREIGN KEY(${column}) REFERENCES ${target}; EXCEPTION WHEN duplicate_object THEN NULL; END $$`),
  `DROP INDEX IF EXISTS feedback_relay_nonces_authority_idx`, `DROP INDEX IF EXISTS feedback_relay_nonces_request_idx`,
  `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_nonces_legacy_authority_idx ON feedback_relay_nonces(audience,key_id,nonce) WHERE authority_version='legacy'`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_nonces_legacy_request_idx ON feedback_relay_nonces(request_id) WHERE authority_version='legacy'`,
  `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_nonces_authority_idx ON feedback_relay_nonces(receiver_id,direction,scope_id,object_id,request_hash,nonce) WHERE authority_version='current'`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_nonces_request_idx ON feedback_relay_nonces(receiver_id,direction,request_id) WHERE authority_version='current'`, `CREATE INDEX IF NOT EXISTS feedback_relay_nonces_expiry_idx ON feedback_relay_nonces(expires_at)`,
  `CREATE OR REPLACE FUNCTION feedback_relay_validate_nonce() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; canonical_scope text; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=NEW.job_id FOR SHARE; canonical_scope:=j.company_id::text||':'||COALESCE(j.project_id::text,'general'); IF NEW.authority_version<>'current' OR NOT FOUND OR ROW(NEW.receiver_id,NEW.direction,NEW.scope_id,NEW.company_id,NEW.project_id,NEW.feedback_id,NEW.asset_id,NEW.object_id,NEW.request_hash) IS DISTINCT FROM ROW(j.destination_id,j.direction,canonical_scope,j.company_id,j.project_id,j.feedback_id,j.asset_id,j.object_id,j.request_hash) THEN RAISE EXCEPTION 'feedback relay nonce scope mismatch'; END IF; RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_nonces_validate BEFORE INSERT ON feedback_relay_nonces FOR EACH ROW EXECUTE FUNCTION feedback_relay_validate_nonce(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE TABLE IF NOT EXISTS feedback_relay_receipts (id bigserial PRIMARY KEY,job_id bigint NOT NULL REFERENCES feedback_relay_jobs(id),job_version integer NOT NULL,fencing_token bigint NOT NULL,relay_mode text NOT NULL,direction text NOT NULL,company_id integer NOT NULL REFERENCES companies(id),project_id integer REFERENCES projects(id),feedback_id integer NOT NULL REFERENCES feedback_items(id),asset_id integer NOT NULL REFERENCES feedback_assets(id),policy_id text NOT NULL,policy_version text NOT NULL,policy_sha256 text NOT NULL,request_hash text NOT NULL,verification_state text NOT NULL DEFAULT 'verified',protocol_version text NOT NULL,request_id text NOT NULL,request_nonce text NOT NULL,destination_id text NOT NULL,object_id text NOT NULL,byte_count bigint NOT NULL,sha256 text NOT NULL,received_at timestamp NOT NULL,receiver_key_id text NOT NULL,canonical_sha256 text NOT NULL,signature text NOT NULL,verified_at timestamp NOT NULL,readback_verified_at timestamp,readback_sha256 text,created_at timestamp NOT NULL DEFAULT now(),CONSTRAINT feedback_relay_receipts_bytes_chk CHECK(byte_count>=0),CONSTRAINT feedback_relay_receipts_hash_chk CHECK(sha256 ~ '^[a-f0-9]{64}$' AND canonical_sha256 ~ '^[a-f0-9]{64}$' AND request_hash ~ '^[a-f0-9]{64}$' AND policy_sha256 ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_receipts_verification_chk CHECK((verification_state='unverified' AND readback_verified_at IS NULL AND readback_sha256 IS NULL) OR (verification_state='verified' AND readback_sha256=sha256 AND verified_at>=received_at AND readback_verified_at>=verified_at AND created_at>=readback_verified_at)))`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_receipts_job_idx ON feedback_relay_receipts(job_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_receipts_request_idx ON feedback_relay_receipts(destination_id,request_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_receipts_destination_object_idx ON feedback_relay_receipts(destination_id,object_id)`,
  `DROP TRIGGER IF EXISTS feedback_relay_receipts_immutable ON feedback_relay_receipts`,
  ...["job_version integer","fencing_token bigint","relay_mode text","direction text","company_id integer","project_id integer","feedback_id integer","asset_id integer","policy_id text","policy_version text","policy_sha256 text","request_hash text","verification_state text NOT NULL DEFAULT 'unverified'"].map(definition => `ALTER TABLE feedback_relay_receipts ADD COLUMN IF NOT EXISTS ${definition}`),
  `ALTER TABLE feedback_relay_receipts ALTER COLUMN verification_state SET DEFAULT 'verified'`,
  ...[["feedback_relay_receipts_company_id_fkey","company_id","companies(id)"],["feedback_relay_receipts_project_id_fkey","project_id","projects(id)"],["feedback_relay_receipts_feedback_id_fkey","feedback_id","feedback_items(id)"],["feedback_relay_receipts_asset_id_fkey","asset_id","feedback_assets(id)"]].map(([name,column,target]) => `DO $$ BEGIN ALTER TABLE feedback_relay_receipts ADD CONSTRAINT ${name} FOREIGN KEY(${column}) REFERENCES ${target}; EXCEPTION WHEN duplicate_object THEN NULL; END $$`),
  `UPDATE feedback_relay_receipts r SET job_version=COALESCE(r.job_version,j.version),fencing_token=COALESCE(r.fencing_token,j.fencing_token),relay_mode=COALESCE(r.relay_mode,j.relay_mode),direction=COALESCE(r.direction,j.direction),company_id=COALESCE(r.company_id,j.company_id),project_id=COALESCE(r.project_id,j.project_id),feedback_id=COALESCE(r.feedback_id,j.feedback_id),asset_id=COALESCE(r.asset_id,j.asset_id),policy_id=COALESCE(r.policy_id,j.policy_id),policy_version=COALESCE(r.policy_version,j.policy_version),policy_sha256=COALESCE(r.policy_sha256,j.policy_sha256),request_hash=COALESCE(r.request_hash,j.request_hash),verification_state=CASE WHEN r.readback_verified_at IS NOT NULL AND r.readback_sha256=r.sha256 THEN 'verified' ELSE 'unverified' END FROM feedback_relay_jobs j WHERE j.id=r.job_id`,
  ...["job_version","fencing_token","relay_mode","direction","company_id","feedback_id","asset_id","policy_id","policy_version","policy_sha256","request_hash","verification_state"].map(column => `ALTER TABLE feedback_relay_receipts ALTER COLUMN ${column} SET NOT NULL`),
  `DROP INDEX IF EXISTS feedback_relay_receipts_request_idx`, `CREATE UNIQUE INDEX feedback_relay_receipts_request_idx ON feedback_relay_receipts(destination_id,request_id)`,
  `ALTER TABLE feedback_relay_receipts DROP CONSTRAINT IF EXISTS feedback_relay_receipts_readback_chk`, `DO $$ BEGIN ALTER TABLE feedback_relay_receipts ADD CONSTRAINT feedback_relay_receipts_verification_chk CHECK((verification_state='unverified' AND readback_verified_at IS NULL AND readback_sha256 IS NULL) OR (verification_state='verified' AND readback_sha256=sha256 AND verified_at>=received_at AND readback_verified_at>=verified_at AND created_at>=readback_verified_at)); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_validate_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=NEW.job_id FOR UPDATE; IF current_setting('bimlog.feedback_relay_receipt_job_id',true) IS DISTINCT FROM NEW.job_id::text OR NOT FOUND OR j.state<>'transferring' OR j.receipt_id IS NOT NULL OR NEW.verification_state<>'verified' OR NEW.readback_verified_at IS NULL OR NEW.readback_sha256 IS NULL OR NEW.job_version<>j.version OR NEW.fencing_token<>j.fencing_token OR ROW(NEW.relay_mode,NEW.direction,NEW.company_id,NEW.project_id,NEW.feedback_id,NEW.asset_id,NEW.policy_id,NEW.policy_version,NEW.policy_sha256,NEW.request_hash,NEW.destination_id,NEW.object_id,NEW.byte_count,NEW.sha256) IS DISTINCT FROM ROW(j.relay_mode,j.direction,j.company_id,j.project_id,j.feedback_id,j.asset_id,j.policy_id,j.policy_version,j.policy_sha256,j.request_hash,j.destination_id,j.object_id,j.source_byte_count,j.source_sha256) THEN RAISE EXCEPTION 'feedback relay receipt mismatch or direct insertion denied'; END IF; RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_receipts_validate BEFORE INSERT ON feedback_relay_receipts FOR EACH ROW EXECUTE FUNCTION feedback_relay_validate_receipt(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE TABLE IF NOT EXISTS feedback_relay_holds (id bigserial PRIMARY KEY,job_id bigint NOT NULL REFERENCES feedback_relay_jobs(id),hold_key text NOT NULL,reason text NOT NULL,placed_by_user_id integer REFERENCES users(id),placed_at timestamp NOT NULL DEFAULT now(),released_by_user_id integer REFERENCES users(id),released_at timestamp,release_reason text,CONSTRAINT feedback_relay_holds_release_chk CHECK((released_at IS NULL AND released_by_user_id IS NULL AND release_reason IS NULL) OR (released_at IS NOT NULL AND released_by_user_id IS NOT NULL AND release_reason IS NOT NULL AND released_at>=placed_at)))`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_holds_key_idx ON feedback_relay_holds(job_id,hold_key)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_holds_active_idx ON feedback_relay_holds(job_id) WHERE released_at IS NULL`,
  `CREATE TABLE IF NOT EXISTS feedback_relay_temporary_objects (id bigserial PRIMARY KEY,job_id bigint NOT NULL REFERENCES feedback_relay_jobs(id),storage_backend text NOT NULL,storage_key text NOT NULL,byte_count bigint NOT NULL,sha256 text NOT NULL,encrypted boolean NOT NULL,created_at timestamp NOT NULL DEFAULT now(),expires_at timestamp NOT NULL,delete_started_at timestamp,deleted_at timestamp,absence_verified_at timestamp,delete_fencing_token bigint,CONSTRAINT feedback_relay_temp_bytes_chk CHECK(byte_count>=0),CONSTRAINT feedback_relay_temp_hash_chk CHECK(sha256 ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_temp_expiry_chk CHECK(expires_at>created_at),CONSTRAINT feedback_relay_temp_delete_chk CHECK((deleted_at IS NULL AND absence_verified_at IS NULL) OR (delete_started_at IS NOT NULL AND deleted_at IS NOT NULL AND absence_verified_at IS NOT NULL AND delete_fencing_token IS NOT NULL AND delete_fencing_token>=0 AND delete_started_at<=deleted_at AND deleted_at<=absence_verified_at)))`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_temp_job_idx ON feedback_relay_temporary_objects(job_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_temp_storage_idx ON feedback_relay_temporary_objects(storage_backend,storage_key)`, `CREATE INDEX IF NOT EXISTS feedback_relay_temp_expiry_idx ON feedback_relay_temporary_objects(expires_at) WHERE deleted_at IS NULL`,
  `CREATE OR REPLACE FUNCTION feedback_relay_validate_temporary_object() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'feedback relay temporary object deletion is metadata-only'; END IF; SELECT * INTO j FROM feedback_relay_jobs WHERE id=NEW.job_id FOR UPDATE; IF NOT FOUND OR j.relay_mode<>'queue' OR (TG_OP='INSERT' AND j.state NOT IN ('queued','transferring')) OR NEW.byte_count<>j.source_byte_count OR NEW.sha256<>j.source_sha256 OR NOT NEW.encrypted THEN RAISE EXCEPTION 'feedback relay temporary object mismatch'; END IF; IF TG_OP='UPDATE' THEN IF ROW(NEW.job_id,NEW.storage_backend,NEW.storage_key,NEW.byte_count,NEW.sha256,NEW.encrypted,NEW.created_at,NEW.expires_at) IS DISTINCT FROM ROW(OLD.job_id,OLD.storage_backend,OLD.storage_key,OLD.byte_count,OLD.sha256,OLD.encrypted,OLD.created_at,OLD.expires_at) OR current_setting('bimlog.feedback_relay_delete_job_id',true) IS DISTINCT FROM NEW.job_id::text OR j.state<>'cleanup-pending' OR j.receipt_id IS NULL OR j.lease_token IS NULL OR j.lease_expires_at<=now() OR NEW.delete_fencing_token<>j.fencing_token OR NEW.absence_verified_at>now() OR EXISTS(SELECT 1 FROM feedback_relay_holds WHERE job_id=j.id AND released_at IS NULL) THEN RAISE EXCEPTION 'feedback relay temporary deletion denied'; END IF; END IF; RETURN NEW; END $$`,
  `DO $$ BEGIN CREATE TRIGGER feedback_relay_temporary_objects_validate BEFORE INSERT OR UPDATE OR DELETE ON feedback_relay_temporary_objects FOR EACH ROW EXECUTE FUNCTION feedback_relay_validate_temporary_object(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE TABLE IF NOT EXISTS feedback_relay_deletion_proofs (id bigserial PRIMARY KEY,job_id bigint NOT NULL REFERENCES feedback_relay_jobs(id),temporary_object_id bigint NOT NULL REFERENCES feedback_relay_temporary_objects(id),receipt_id bigint NOT NULL REFERENCES feedback_relay_receipts(id),approval_id text NOT NULL,approved_by_user_id integer NOT NULL REFERENCES users(id),inventory jsonb NOT NULL,inventory_sha256 text NOT NULL,deleted_at timestamp NOT NULL,absence_verified_at timestamp NOT NULL,proof_sha256 text NOT NULL,created_at timestamp NOT NULL DEFAULT now(),CONSTRAINT feedback_relay_deletion_hash_chk CHECK(inventory_sha256 ~ '^[a-f0-9]{64}$' AND proof_sha256 ~ '^[a-f0-9]{64}$'),CONSTRAINT feedback_relay_deletion_order_chk CHECK(deleted_at<=absence_verified_at AND absence_verified_at<=created_at))`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_deletion_job_idx ON feedback_relay_deletion_proofs(job_id)`, `CREATE UNIQUE INDEX IF NOT EXISTS feedback_relay_deletion_temp_idx ON feedback_relay_deletion_proofs(temporary_object_id)`,
  `DO $$ BEGIN ALTER TABLE feedback_relay_jobs ADD CONSTRAINT feedback_relay_jobs_receipt_id_fkey FOREIGN KEY(receipt_id) REFERENCES feedback_relay_receipts(id); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `DO $$ BEGIN ALTER TABLE feedback_relay_jobs ADD CONSTRAINT feedback_relay_jobs_deletion_proof_id_fkey FOREIGN KEY(deletion_proof_id) REFERENCES feedback_relay_deletion_proofs(id); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_validate_deletion_proof() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; r feedback_relay_receipts%ROWTYPE; t feedback_relay_temporary_objects%ROWTYPE; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=NEW.job_id FOR UPDATE; IF current_setting('bimlog.feedback_relay_deletion_job_id',true) IS DISTINCT FROM NEW.job_id::text OR NOT FOUND OR j.state<>'cleanup-pending' OR j.receipt_id IS NULL OR j.deletion_proof_id IS NOT NULL OR j.lease_token IS NULL OR j.lease_expires_at<=now() THEN RAISE EXCEPTION 'feedback relay deletion proof state mismatch or direct insertion denied'; END IF; SELECT * INTO r FROM feedback_relay_receipts WHERE id=NEW.receipt_id AND job_id=NEW.job_id FOR SHARE; IF NOT FOUND OR r.id<>j.receipt_id OR r.verification_state<>'verified' OR r.readback_verified_at IS NULL THEN RAISE EXCEPTION 'feedback relay verified receipt/readback required'; END IF; SELECT * INTO t FROM feedback_relay_temporary_objects WHERE id=NEW.temporary_object_id AND job_id=NEW.job_id FOR UPDATE; IF NOT FOUND OR t.absence_verified_at IS NULL OR t.deleted_at IS NULL OR t.delete_fencing_token<>j.fencing_token THEN RAISE EXCEPTION 'feedback relay absence/fencing proof required'; END IF; IF EXISTS(SELECT 1 FROM feedback_relay_holds WHERE job_id=NEW.job_id AND released_at IS NULL) THEN RAISE EXCEPTION 'feedback relay active hold prevents deletion proof'; END IF; IF NEW.deleted_at<>t.deleted_at OR NEW.absence_verified_at<>t.absence_verified_at OR NEW.deleted_at<r.readback_verified_at THEN RAISE EXCEPTION 'feedback relay deletion proof ordering mismatch'; END IF; RETURN NEW; END $$`, `DO $$ BEGIN CREATE TRIGGER feedback_relay_deletion_proofs_validate BEFORE INSERT ON feedback_relay_deletion_proofs FOR EACH ROW EXECUTE FUNCTION feedback_relay_validate_deletion_proof(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'feedback relay evidence is immutable'; END $$`,
  ...["feedback_relay_custody_events","feedback_relay_nonces","feedback_relay_receipts","feedback_relay_deletion_proofs"].map(table => `DO $$ BEGIN CREATE TRIGGER ${table}_immutable BEFORE UPDATE OR DELETE ON ${table} FOR EACH ROW EXECUTE FUNCTION feedback_relay_reject_mutation(); EXCEPTION WHEN duplicate_object THEN NULL; END $$`),
  `CREATE OR REPLACE FUNCTION feedback_relay_transition_job(p_job_id bigint,p_observed_version integer,p_lease_token text,p_fencing_token bigint,p_to_state text,p_event_id text,p_event_type text,p_actor_type text,p_actor_id text,p_reason_code text,p_receipt_id bigint DEFAULT NULL,p_deletion_proof_id bigint DEFAULT NULL,p_expiry_outcome text DEFAULT NULL) RETURNS feedback_relay_jobs LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; result feedback_relay_jobs%ROWTYPE; next_sequence integer; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=p_job_id FOR UPDATE; IF NOT FOUND OR p_lease_token IS NULL OR j.version<>p_observed_version OR j.fencing_token<>p_fencing_token OR j.lease_token IS DISTINCT FROM p_lease_token OR j.lease_expires_at<=now() THEN RAISE EXCEPTION 'feedback relay stale transition authority'; END IF; IF p_to_state='transferring' AND NOT EXISTS(SELECT 1 FROM feedback_assets WHERE id=j.asset_id AND feedback_id=j.feedback_id AND scan_state='clean' AND scanned_at IS NOT NULL AND byte_size=j.source_byte_count AND sha256=j.source_sha256) THEN RAISE EXCEPTION 'feedback relay clean scan authority lost'; END IF; IF EXISTS(SELECT 1 FROM feedback_relay_holds WHERE job_id=j.id AND released_at IS NULL) AND p_to_state<>'held' THEN RAISE EXCEPTION 'feedback relay active hold prevents transition'; END IF; IF NOT ((j.state='queued' AND p_to_state IN ('transferring','held','manual-review','expired')) OR (j.state='transferring' AND p_to_state IN ('queued','receipt-verified','held','manual-review')) OR (j.state='receipt-verified' AND ((j.relay_mode='queue' AND p_to_state IN ('cleanup-pending','held','manual-review')) OR (j.relay_mode='direct' AND p_to_state IN ('delivered','held','manual-review')))) OR (j.state='cleanup-pending' AND p_to_state IN ('delivered','held','manual-review')) OR (j.state='delivered' AND p_to_state IN ('held','manual-review')) OR (j.state='manual-review' AND p_to_state IN ('queued','held')) OR (j.state='held' AND p_to_state IN ('queued','manual-review'))) THEN RAISE EXCEPTION 'feedback relay illegal state transition'; END IF; IF p_to_state='receipt-verified' AND (p_receipt_id IS NULL OR NOT EXISTS(SELECT 1 FROM feedback_relay_receipts WHERE id=p_receipt_id AND job_id=j.id AND verification_state='verified' AND readback_verified_at IS NOT NULL)) THEN RAISE EXCEPTION 'feedback relay verified receipt required'; END IF; IF p_to_state='cleanup-pending' AND (j.receipt_id IS NULL OR j.relay_mode<>'queue' OR NOT EXISTS(SELECT 1 FROM feedback_relay_temporary_objects WHERE job_id=j.id AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'feedback relay queued receipt and temporary custody required'; END IF; IF p_to_state='delivered' AND ((j.relay_mode='direct' AND EXISTS(SELECT 1 FROM feedback_relay_temporary_objects WHERE job_id=j.id)) OR (j.relay_mode='queue' AND (j.state<>'cleanup-pending' OR j.deletion_proof_id IS NULL))) THEN RAISE EXCEPTION 'feedback relay delivery prerequisites missing'; END IF; IF p_to_state='expired' AND (j.state<>'queued' OR j.expires_at IS NULL OR j.expires_at>now() OR p_expiry_outcome IS NULL OR j.receipt_id IS NOT NULL OR EXISTS(SELECT 1 FROM feedback_relay_holds WHERE job_id=j.id AND released_at IS NULL) OR EXISTS(SELECT 1 FROM feedback_relay_temporary_objects WHERE job_id=j.id AND deleted_at IS NOT NULL) OR EXISTS(SELECT 1 FROM feedback_relay_temporary_objects WHERE job_id=j.id AND delete_started_at IS NOT NULL AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'feedback relay guarded expiry prerequisites missing'; END IF; SELECT COALESCE(max(sequence),0)+1 INTO next_sequence FROM feedback_relay_custody_events WHERE job_id=j.id; PERFORM set_config('bimlog.feedback_relay_transition_job_id',j.id::text,true); UPDATE feedback_relay_jobs SET state=p_to_state,version=version+1,receipt_id=COALESCE(receipt_id,p_receipt_id),deletion_proof_id=COALESCE(deletion_proof_id,p_deletion_proof_id),expiry_outcome=CASE WHEN p_to_state='expired' THEN p_expiry_outcome ELSE NULL END,updated_at=now() WHERE id=j.id RETURNING * INTO result; INSERT INTO feedback_relay_custody_events(job_id,sequence,event_id,event_type,from_state,to_state,job_version,fencing_token,actor_type,actor_id,reason_code) VALUES(j.id,next_sequence,p_event_id,p_event_type,j.state,p_to_state,result.version,j.fencing_token,p_actor_type,p_actor_id,p_reason_code); RETURN result; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_record_receipt(p_job_id bigint,p_observed_version integer,p_lease_token text,p_fencing_token bigint,p_protocol_version text,p_request_id text,p_request_nonce text,p_received_at timestamp,p_receiver_key_id text,p_canonical_sha256 text,p_signature text,p_verified_at timestamp,p_readback_verified_at timestamp,p_event_id text) RETURNS feedback_relay_jobs LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; receipt_id bigint; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=p_job_id FOR UPDATE; IF NOT FOUND OR j.version<>p_observed_version OR j.fencing_token<>p_fencing_token OR j.lease_token IS DISTINCT FROM p_lease_token OR j.lease_expires_at<=now() OR j.state<>'transferring' THEN RAISE EXCEPTION 'feedback relay stale receipt authority'; END IF; PERFORM set_config('bimlog.feedback_relay_receipt_job_id',j.id::text,true); INSERT INTO feedback_relay_receipts(job_id,job_version,fencing_token,relay_mode,direction,company_id,project_id,feedback_id,asset_id,policy_id,policy_version,policy_sha256,request_hash,verification_state,protocol_version,request_id,request_nonce,destination_id,object_id,byte_count,sha256,received_at,receiver_key_id,canonical_sha256,signature,verified_at,readback_verified_at,readback_sha256) VALUES(j.id,j.version,j.fencing_token,j.relay_mode,j.direction,j.company_id,j.project_id,j.feedback_id,j.asset_id,j.policy_id,j.policy_version,j.policy_sha256,j.request_hash,'verified',p_protocol_version,p_request_id,p_request_nonce,j.destination_id,j.object_id,j.source_byte_count,j.source_sha256,p_received_at,p_receiver_key_id,p_canonical_sha256,p_signature,p_verified_at,p_readback_verified_at,j.source_sha256) RETURNING id INTO receipt_id; RETURN feedback_relay_transition_job(j.id,j.version,j.lease_token,j.fencing_token,'receipt-verified',p_event_id,'receipt-verified','receiver',p_receiver_key_id,'verified-receipt',receipt_id); END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_mark_temporary_deleted(p_job_id bigint,p_observed_version integer,p_lease_token text,p_fencing_token bigint,p_temporary_object_id bigint,p_delete_started_at timestamp,p_deleted_at timestamp,p_absence_verified_at timestamp) RETURNS feedback_relay_temporary_objects LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; result feedback_relay_temporary_objects%ROWTYPE; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=p_job_id FOR UPDATE; IF NOT FOUND OR j.version<>p_observed_version OR j.fencing_token<>p_fencing_token OR j.lease_token IS DISTINCT FROM p_lease_token OR j.state<>'cleanup-pending' OR j.receipt_id IS NULL THEN RAISE EXCEPTION 'feedback relay stale deletion authority'; END IF; PERFORM set_config('bimlog.feedback_relay_delete_job_id',j.id::text,true); UPDATE feedback_relay_temporary_objects SET delete_started_at=p_delete_started_at,deleted_at=p_deleted_at,absence_verified_at=p_absence_verified_at,delete_fencing_token=j.fencing_token WHERE id=p_temporary_object_id AND job_id=j.id RETURNING * INTO result; IF NOT FOUND THEN RAISE EXCEPTION 'feedback relay temporary object missing'; END IF; RETURN result; END $$`,
  `CREATE OR REPLACE FUNCTION feedback_relay_record_deletion_proof(p_job_id bigint,p_observed_version integer,p_lease_token text,p_fencing_token bigint,p_temporary_object_id bigint,p_approval_id text,p_approved_by_user_id integer,p_inventory jsonb,p_inventory_sha256 text,p_proof_sha256 text,p_event_id text) RETURNS feedback_relay_jobs LANGUAGE plpgsql AS $$ DECLARE j feedback_relay_jobs%ROWTYPE; t feedback_relay_temporary_objects%ROWTYPE; proof_id bigint; next_sequence integer; result feedback_relay_jobs%ROWTYPE; BEGIN SELECT * INTO j FROM feedback_relay_jobs WHERE id=p_job_id FOR UPDATE; SELECT * INTO t FROM feedback_relay_temporary_objects WHERE id=p_temporary_object_id AND job_id=p_job_id FOR UPDATE; IF NOT FOUND OR j.version<>p_observed_version OR j.fencing_token<>p_fencing_token OR j.lease_token IS DISTINCT FROM p_lease_token OR j.state<>'cleanup-pending' OR j.receipt_id IS NULL OR j.deletion_proof_id IS NOT NULL OR t.absence_verified_at IS NULL THEN RAISE EXCEPTION 'feedback relay stale deletion proof authority'; END IF; PERFORM set_config('bimlog.feedback_relay_deletion_job_id',j.id::text,true); INSERT INTO feedback_relay_deletion_proofs(job_id,temporary_object_id,receipt_id,approval_id,approved_by_user_id,inventory,inventory_sha256,deleted_at,absence_verified_at,proof_sha256) VALUES(j.id,t.id,j.receipt_id,p_approval_id,p_approved_by_user_id,p_inventory,p_inventory_sha256,t.deleted_at,t.absence_verified_at,p_proof_sha256) RETURNING id INTO proof_id; SELECT COALESCE(max(sequence),0)+1 INTO next_sequence FROM feedback_relay_custody_events WHERE job_id=j.id; PERFORM set_config('bimlog.feedback_relay_transition_job_id',j.id::text,true); UPDATE feedback_relay_jobs SET deletion_proof_id=proof_id,version=version+1,updated_at=now() WHERE id=j.id RETURNING * INTO result; INSERT INTO feedback_relay_custody_events(job_id,sequence,event_id,event_type,from_state,to_state,job_version,fencing_token,actor_type,actor_id,reason_code) VALUES(j.id,next_sequence,p_event_id,'deletion-proven',j.state,j.state,result.version,j.fencing_token,'operator',p_approved_by_user_id::text,'verified-deletion-proof'); RETURN result; END $$`,
];
